OUT = (["Outdoor space", "Schoolyards and parks nearby", "Yards may be small; corridors and courtyards work"], ["Không gian ngoài trời", "Có sân trường và công viên gần", "Sân có thể nhỏ; dùng hành lang, sân trong"])
SPK = (["Speaking", "Students used to sharing ideas aloud", "Students may be shy to speak alone"], ["Nói", "Học sinh quen nói ý kiến", "Học sinh có thể ngại nói một mình"])
INC = (["Inclusion", "Support staff and IEPs for learners with special needs", "Inclusive classes are growing; support staff may be limited"], ["Hòa nhập", "Có nhân viên hỗ trợ và kế hoạch giáo dục cá nhân", "Lớp hòa nhập ngày càng nhiều; nhân sự hỗ trợ còn hạn chế"])
MUS = "The Arts, Grades 1–8 (2009): music · Language, Grades 1–8 (2023) · STEP 1–2"
PE = "Health and Physical Education (2019) · Language, Grades 1–8 (2023) · STEP 1–2"

A("G075", "pass-the-ball-names", "Pass the Ball", "Pass the Ball", "Chuyền bóng",
  "listening-speaking", "beginner", "STEP 1", "Pre-A1–A1", "1-3", "10-15", "8-35", "floor", "Pass the ball", "My name is Linh. | I like red!", "name,like,ball",
  ("A soft ball; music to start and stop.", "Một quả bóng mềm; nhạc để bắt đầu và dừng."),
  ex(("B13", "Say a short sentence about yourself."), ("B11", "Listen to classmates and remember names."), ("A12", "Join in a whole-group game.")),
  ("Passing a ball gives every child a turn and a clear signal to speak. It is ideal for very young learners and newcomers who need short, safe chances to talk.",
   "Chuyền bóng cho mỗi em một lượt và một tín hiệu rõ ràng để nói. Rất phù hợp với trẻ nhỏ và học sinh mới đến cần những cơ hội nói ngắn và an toàn."),
  [("Sit in a circle", "Children sit in a circle; the teacher models with the ball.", "Ngồi vòng tròn", "Trẻ ngồi thành vòng tròn; giáo viên làm mẫu với quả bóng."),
   ("Name round", "Pass the ball; each child says \"My name is…\".", "Vòng tên", "Chuyền bóng; mỗi em nói \"My name is…\"."),
   ("Music stop", "Pass while music plays; the child holding it when the music stops says a sentence.", "Nhạc dừng", "Chuyền khi nhạc bật; em giữ bóng khi nhạc tắt nói một câu."),
   ("Remember", "The holder says a friend's name and passes to them.", "Ghi nhớ", "Em giữ bóng gọi tên một bạn và chuyền cho bạn đó."),
   ("Goodbye round", "Each child says \"Goodbye, ___!\" as they pass.", "Vòng chào tạm biệt", "Mỗi em nói \"Goodbye, ___!\" khi chuyền bóng.")],
  (["We are learning to introduce ourselves.", "We are learning classmates' names."], ["Chúng ta học cách giới thiệu bản thân.", "Chúng ta học tên các bạn trong lớp."]),
  (["I can say my name.", "I can say one thing I like.", "I can say a friend's name."], ["Em có thể nói tên mình.", "Em có thể nói một điều em thích.", "Em có thể gọi tên một bạn."]),
  ("pass without speaking at first; say one word later.", "lúc đầu chuyền mà không cần nói; sau đó nói một từ."), ("add age and a favourite food.", "thêm tuổi và món ăn yêu thích."),
  ("willingness to speak", "sự sẵn sàng nói"), ("Of learning: each child says two sentences about themselves.", "Đánh giá kết quả học tập: mỗi em nói hai câu về bản thân."),
  (["Soft ball", "Music"], ["Bóng mềm", "Nhạc"]), SPK,
  ("Pass along rows and back, row by row.", "Chuyền dọc dãy rồi quay lại, lần lượt từng dãy."),
  ("Link to GDPT 2018 Grade 3: greetings and introductions.", "Gắn với GDPT 2018 lớp 3: chào hỏi và giới thiệu."),
  ("a ball makes the first weeks of English warm and welcoming.", "quả bóng giúp những tuần đầu học tiếng Anh ấm áp và thân thiện."),
  ("Let a child pass without speaking if they are not ready. Being allowed to stay quiet once is often what makes them speak next time.", "Cho phép trẻ chuyền mà không nói nếu chưa sẵn sàng. Được im lặng một lần thường là điều khiến trẻ dám nói ở lần sau."), prog=PE)

A("G076", "nature-scavenger-hunt", "Outdoor Learning", "Nature Scavenger Hunt", "Truy tìm báu vật thiên nhiên",
  "integrated;reading", "beginner;intermediate", "STEP 1–3", "A1–A2", "1-3;3-8", "30-40", "10-40", "floor", "Nature hunt", "Find something smooth! | I found a smooth stone!", "leaf,stone,rough,smooth",
  ("Scavenger-hunt lists (something green, rough, smooth, small); bags; adult supervision outdoors.", "Danh sách truy tìm (thứ màu xanh, sần sùi, nhẵn, nhỏ); túi đựng; có người lớn giám sát ngoài trời."),
  ex(("C24", "Read a list and check understanding while searching."), ("B22", "Use describing words (rough, smooth, soft)."), ("B13", "Report findings to the group.")),
  ("Outdoor hunting gets children reading with a purpose and touching what the words mean. Describing their finds builds adjective vocabulary through real experience.",
   "Truy tìm ngoài trời giúp trẻ đọc có mục đích và chạm vào chính những gì từ ngữ mô tả. Mô tả những thứ tìm được xây dựng vốn tính từ qua trải nghiệm thật."),
  [("Read the list", "Read the hunt list together; act out each adjective.", "Đọc danh sách", "Cùng đọc danh sách; diễn tả từng tính từ."),
   ("Safety rules", "Stay in the area; don't pick flowers or touch insects.", "Quy tắc an toàn", "Ở trong khu vực; không hái hoa, không chạm côn trùng."),
   ("Hunt", "Teams find and collect items on the list.", "Truy tìm", "Các đội tìm và thu thập đồ vật trong danh sách."),
   ("Show and tell", "Teams describe their finds: \"This stone is smooth.\"", "Khoe và kể", "Các đội mô tả: \"This stone is smooth.\""),
   ("Return", "Return natural items to where they were found.", "Trả lại", "Trả đồ vật tự nhiên về chỗ cũ.")],
  (["We are learning describing words.", "We are learning to read a list and find things."], ["Chúng ta học tính từ mô tả.", "Chúng ta học cách đọc danh sách và tìm đồ vật."]),
  (["I can read the list.", "I can find things that match the words.", "I can describe what I found."], ["Em có thể đọc danh sách.", "Em có thể tìm thứ khớp với từ.", "Em có thể mô tả thứ em tìm được."]),
  ("a picture list and a buddy.", "danh sách bằng tranh và có bạn đi cùng."), ("compare two finds with comparatives.", "so sánh hai thứ tìm được bằng so sánh hơn."),
  ("adjectives used in descriptions", "tính từ dùng khi mô tả"), ("Of learning: a completed list with one sentence per item.", "Đánh giá kết quả học tập: danh sách hoàn chỉnh, mỗi mục một câu."),
  (["Hunt lists", "Bags"], ["Danh sách truy tìm", "Túi đựng"]), OUT,
  ("Hunt in the school yard in turns by row, or hide items in the classroom.", "Truy tìm ở sân trường theo lượt từng dãy, hoặc giấu đồ trong lớp."),
  ("Link to GDPT 2018 Grades 3–5: nature and outdoor activities.", "Gắn với GDPT 2018 lớp 3–5: thiên nhiên và hoạt động ngoài trời."),
  ("a 20-minute yard hunt makes adjectives concrete.", "truy tìm 20 phút ở sân trường giúp tính từ trở nên cụ thể."),
  ("Include one item nobody can collect, like \"something that makes a sound\". Teams must describe it instead, which is excellent speaking.", "Thêm một mục không thể mang về, như \"thứ gì đó phát ra âm thanh\". Các đội phải mô tả thay vì mang về, rất tốt để luyện nói."), prog=PE)

A("G077", "nature-collage", "Outdoor Learning with Art & Craft", "Nature Collage", "Tranh ghép thiên nhiên",
  "integrated;writing", "beginner", "STEP 1–2", "A1", "1-3", "30-40", "8-35", "table", "Nature collage", "I used three leaves. | My picture is a bird!", "leaf,twig,petal,glue",
  ("Collected leaves, twigs, fallen petals; card and glue; label strips.", "Lá, cành nhỏ, cánh hoa rụng đã thu thập; bìa và keo; dải giấy ghi nhãn."),
  ex(("B22", "Name natural materials and count them."), ("D11", "Write a label or caption for an artwork."), ("B13", "Describe their picture to others.")),
  ("Making pictures from nature combines creativity with counting and naming. A caption turns each artwork into a tiny piece of writing that children are proud to display.",
   "Làm tranh từ vật liệu thiên nhiên kết hợp sáng tạo với đếm và gọi tên. Một dòng chú thích biến mỗi bức tranh thành bài viết nhỏ mà trẻ tự hào treo lên."),
  [("Collect", "Collect fallen leaves and twigs outside.", "Thu thập", "Nhặt lá rụng và cành nhỏ ngoài sân."),
   ("Name and count", "Sort materials and count: \"I have five leaves.\"", "Gọi tên và đếm", "Phân loại vật liệu và đếm: \"I have five leaves.\""),
   ("Create", "Children arrange and glue a picture (animal, face, house).", "Sáng tạo", "Trẻ sắp xếp và dán thành tranh (con vật, khuôn mặt, ngôi nhà)."),
   ("Caption", "Children write a caption: \"This is a bird. I used three leaves.\"", "Chú thích", "Trẻ viết chú thích: \"This is a bird. I used three leaves.\""),
   ("Gallery", "Children walk the gallery and say one thing they like.", "Triển lãm", "Trẻ đi xem triển lãm và nói một điều mình thích.")],
  (["We are learning nature words.", "We are learning to write a caption."], ["Chúng ta học từ về thiên nhiên.", "Chúng ta học cách viết chú thích."]),
  (["I can name the materials.", "I can count what I used.", "I can write a caption."], ["Em có thể gọi tên vật liệu.", "Em có thể đếm số vật liệu đã dùng.", "Em có thể viết chú thích."]),
  ("copy a model caption.", "chép chú thích mẫu."), ("write a 3-sentence description of the collage.", "viết đoạn mô tả bức tranh 3 câu."),
  ("counting and naming", "việc đếm và gọi tên"), ("Of learning: collage with caption.", "Đánh giá kết quả học tập: tranh ghép có chú thích."),
  (["Natural materials", "Card and glue", "Label strips"], ["Vật liệu tự nhiên", "Bìa và keo", "Dải giấy ghi nhãn"]), OUT,
  ("Collect materials during break time or as homework.", "Thu thập vật liệu trong giờ ra chơi hoặc giao về nhà."),
  ("Link to Mỹ thuật lớp 1–3 and GDPT 2018 nature topics.", "Gắn với Mỹ thuật lớp 1–3 và chủ đề thiên nhiên GDPT 2018."),
  ("free natural materials make art and English possible anywhere.", "vật liệu tự nhiên miễn phí giúp học mỹ thuật và tiếng Anh ở bất cứ đâu."),
  ("Only collect things already on the ground. It is a simple rule that teaches respect for nature and gives a useful phrase: \"on the ground\".", "Chỉ nhặt những thứ đã rơi xuống đất. Quy tắc đơn giản dạy sự tôn trọng thiên nhiên và cho một cụm từ hữu ích: \"on the ground\"."), prog="The Arts, Grades 1–8 (2009) · Language, Grades 1–8 (2023) · STEP 1–2")

A("G078", "holiday-postcards", "Christmas Field Trip", "Holiday Trip Postcards", "Bưu thiếp chuyến đi mùa lễ hội",
  "writing;integrated", "beginner;intermediate", "STEP 2–3", "A1–A2", "3-8", "30-35", "10-45", "table", "Dear friend…", "Dear Anna, Today we went to… | See you soon!", "Dear,went,saw,love",
  ("Blank postcards; photos from a trip to a holiday market or decorated street; a model postcard.", "Bưu thiếp trắng; ảnh chuyến đi chợ phiên hoặc phố trang trí mùa lễ hội; bưu thiếp mẫu."),
  ex(("D11", "Write a postcard for a real reader."), ("B32", "Use past tense to describe a trip."), ("B33", "Use correct greeting and closing punctuation.")),
  ("A postcard is a short, real text with a clear reader and format. Writing about a festive trip in the past tense gives students something exciting to share.",
   "Bưu thiếp là văn bản ngắn, thật, có người đọc và hình thức rõ ràng. Viết về chuyến đi mùa lễ hội bằng thì quá khứ cho học sinh điều thú vị để chia sẻ."),
  [("Remember the trip", "Look at photos; list things students saw and did.", "Nhớ lại chuyến đi", "Xem ảnh; liệt kê những gì học sinh đã thấy và làm."),
   ("Study a postcard", "Read a model; label greeting, body, closing, address.", "Đọc bưu thiếp mẫu", "Đọc mẫu; ghi tên phần chào, thân, kết, địa chỉ."),
   ("Draft", "Students draft 4–5 sentences in the past tense.", "Viết nháp", "Học sinh viết nháp 4–5 câu ở thì quá khứ."),
   ("Write the postcard", "Students copy neatly and draw a picture on the front.", "Viết bưu thiếp", "Học sinh chép sạch và vẽ tranh mặt trước."),
   ("Send", "Swap postcards with another class or send to a pen pal.", "Gửi đi", "Đổi bưu thiếp với lớp khác hoặc gửi cho bạn qua thư.")],
  (["We are learning to write a postcard.", "We are learning to describe a trip in the past tense."], ["Chúng ta học cách viết bưu thiếp.", "Chúng ta học cách kể về chuyến đi bằng thì quá khứ."]),
  (["I can use a greeting and closing.", "I can write 4 sentences in the past tense.", "I can describe what I saw."], ["Em có thể dùng lời chào đầu và lời kết.", "Em có thể viết 4 câu ở thì quá khứ.", "Em có thể mô tả những gì em thấy."]),
  ("a postcard frame with verbs.", "khung bưu thiếp có sẵn động từ."), ("add feelings and a question for the reader.", "thêm cảm xúc và một câu hỏi cho người đọc."),
  ("past-tense verbs", "các động từ quá khứ"), ("Of learning: the finished postcard.", "Đánh giá kết quả học tập: bưu thiếp hoàn chỉnh."),
  (["Blank postcards", "Trip photos", "Model postcard"], ["Bưu thiếp trắng", "Ảnh chuyến đi", "Bưu thiếp mẫu"]),
  (["Festivals", "Holiday markets and lights in December", "Christmas streets and Tết markets are popular outings"], ["Lễ hội", "Chợ phiên và đèn trang trí tháng 12", "Phố Giáng sinh và chợ Tết là điểm đi chơi phổ biến"]),
  ("Use Tết market photos if there is no Christmas trip.", "Dùng ảnh chợ Tết nếu không có chuyến đi Giáng sinh."),
  ("Link to GDPT 2018 Grades 5–7: festivals, past tense and writing letters.", "Gắn với GDPT 2018 lớp 5–7: lễ hội, thì quá khứ và viết thư."),
  ("postcards to a partner school abroad give writing a real audience.", "bưu thiếp gửi trường kết nghĩa ở nước ngoài cho bài viết một người đọc thật."),
  ("Connect with a class in Ontario or Vietnam and swap postcards. Waiting for a real reply is the best motivation to write.", "Kết nối với một lớp ở Ontario hoặc Việt Nam và trao đổi bưu thiếp. Chờ thư hồi âm thật là động lực viết tốt nhất."))

A("G079", "splash-vocabulary", "Junior Kids – Water Fun", "Splash Vocabulary", "Té nước từ vựng",
  "vocab-grammar;listening-speaking", "beginner", "STEP 1", "Pre-A1–A1", "1-3", "15-20", "8-30", "floor", "Splash!", "Splash the word 'sun'! | Hot! Sunny!", "sun,hot,swim,beach",
  ("Word cards on a wall or ground outdoors; wet sponges or water spray bottles; towels; summer pictures.", "Thẻ từ dán trên tường hoặc sân ngoài trời; bọt biển ướt hoặc bình xịt nước; khăn; tranh mùa hè."),
  ex(("B22", "Recognize summer and weather vocabulary."), ("B11", "Listen and respond to a word called out."), ("A12", "Follow game rules outdoors safely.")),
  ("A water game on a hot day is pure joy, and joy helps memory. Children hear a word, find it and splash it, connecting sound, print and meaning in seconds.",
   "Trò chơi té nước ngày nóng mang lại niềm vui trọn vẹn, và niềm vui giúp ghi nhớ. Trẻ nghe từ, tìm và té nước vào đó, nối âm, chữ và nghĩa chỉ trong vài giây."),
  [("Summer words", "Teach sun, hot, swim, beach, ice cream with pictures.", "Từ về mùa hè", "Dạy sun, hot, swim, beach, ice cream bằng tranh."),
   ("Rules", "Splash only the cards, never people.", "Luật chơi", "Chỉ té vào thẻ, không té vào người."),
   ("Splash the word", "Call a word; one child per team splashes it.", "Té vào từ", "Gọi một từ; mỗi đội một em té nước vào thẻ đó."),
   ("Say a sentence", "The splasher says a sentence: \"It is hot.\"", "Nói một câu", "Em vừa té nói một câu: \"It is hot.\""),
   ("Dry off", "Count points and review words while drying off.", "Lau khô", "Đếm điểm và ôn từ khi lau khô.")],
  (["We are learning summer words."], ["Chúng ta học từ về mùa hè."]),
  (["I can find the word I hear.", "I can say a sentence with the word.", "I can play safely."], ["Em có thể tìm từ em nghe.", "Em có thể nói một câu với từ đó.", "Em có thể chơi an toàn."]),
  ("cards with pictures.", "thẻ có tranh."), ("call a definition instead of the word.", "đọc định nghĩa thay vì đọc từ."),
  ("word recognition", "khả năng nhận diện từ"), ("Of learning: each child reads 4 summer words.", "Đánh giá kết quả học tập: mỗi em đọc 4 từ về mùa hè."),
  (["Word cards", "Sponges or spray bottles", "Towels"], ["Thẻ từ", "Bọt biển hoặc bình xịt", "Khăn"]), OUT,
  ("Use dry sponges or bean bags indoors.", "Dùng bọt biển khô hoặc túi đậu nếu chơi trong lớp."),
  ("Link to GDPT 2018 Grades 3–4: weather and holidays.", "Gắn với GDPT 2018 lớp 3–4: thời tiết và kỳ nghỉ."),
  ("an end-of-year water game is a memorable review.", "trò chơi té nước cuối năm là buổi ôn tập đáng nhớ."),
  ("Laminate the word cards. They survive the water and can be used again every summer.", "Ép plastic các thẻ từ. Thẻ không bị nước làm hỏng và dùng lại được mỗi mùa hè."), prog=PE)

A("G080", "class-band", "Music Band – Hands-on Learning", "Our Class Band", "Ban nhạc của lớp",
  "integrated;listening-speaking", "beginner", "STEP 1–2", "A1", "1-3;3-8", "30-40", "8-40", "board", "Class band", "Play loud! | Now play soft!", "loud,soft,fast,slow",
  ("Home-made instruments (rice shakers, box guitars, pot drums); a simple English song.", "Nhạc cụ tự làm (lọ gạo lắc, đàn hộp, trống nồi); một bài hát tiếng Anh đơn giản."),
  ex(("B11", "Follow musical instructions (loud, soft, fast, slow)."), ("B22", "Name instruments and sound words."), ("B23", "Sing lyrics with rhythm and expression.")),
  ("Making instruments and playing together teaches opposites (loud/soft, fast/slow) through sound. Singing in English builds rhythm, pronunciation and confidence.",
   "Tự làm nhạc cụ và cùng chơi dạy các cặp từ trái nghĩa (to/nhỏ, nhanh/chậm) qua âm thanh. Hát tiếng Anh xây dựng nhịp điệu, phát âm và sự tự tin."),
  [("Make instruments", "Make shakers and drums from recycled items.", "Làm nhạc cụ", "Làm lọ lắc và trống từ đồ tái chế."),
   ("Sound words", "Teach loud, soft, fast, slow with actions.", "Từ về âm thanh", "Dạy loud, soft, fast, slow kèm động tác."),
   ("Conductor game", "The teacher conducts; the band follows the words.", "Trò nhạc trưởng", "Giáo viên làm nhạc trưởng; ban nhạc làm theo lời."),
   ("Sing together", "Sing a simple song with the instruments.", "Cùng hát", "Hát một bài đơn giản cùng nhạc cụ."),
   ("Student conductor", "Students take turns being the conductor.", "Học sinh làm nhạc trưởng", "Học sinh lần lượt làm nhạc trưởng.")],
  (["We are learning sound words and opposites.", "We are learning to sing in English."], ["Chúng ta học từ về âm thanh và từ trái nghĩa.", "Chúng ta học hát tiếng Anh."]),
  (["I can follow loud/soft and fast/slow.", "I can name my instrument.", "I can give an instruction as conductor."], ["Em có thể làm theo to/nhỏ và nhanh/chậm.", "Em có thể gọi tên nhạc cụ của em.", "Em có thể làm nhạc trưởng và ra lệnh."]),
  ("follow gestures first, then words.", "làm theo cử chỉ trước, rồi đến lời."), ("write a new verse for the song.", "viết thêm một lời mới cho bài hát."),
  ("response to instructions", "việc phản ứng theo chỉ dẫn"), ("Of learning: conducting turn with 3 correct instructions.", "Đánh giá kết quả học tập: lượt làm nhạc trưởng với 3 chỉ dẫn đúng."),
  (["Recycled materials", "Song lyrics"], ["Vật liệu tái chế", "Lời bài hát"]), (["Music", "Music class weekly", "Music is loved; English songs are a popular way to learn"], ["Âm nhạc", "Giờ âm nhạc hằng tuần", "Học sinh yêu âm nhạc; bài hát tiếng Anh là cách học được ưa chuộng"]),
  ("Use pencils and desks as drums; no materials needed.", "Dùng bút chì và mặt bàn làm trống; không cần đồ dùng."),
  ("Link to Âm nhạc lớp 1–5 and GDPT 2018 songs and chants in each unit.", "Gắn với Âm nhạc lớp 1–5 và bài hát, chant trong mỗi Unit GDPT 2018."),
  ("desk drumming gives a 45-student orchestra in seconds.", "gõ bàn tạo ngay một dàn nhạc 45 em."),
  ("Agree on a \"stop\" signal (hands up, silence) before giving out instruments. It saves your voice and the lesson.", "Thống nhất tín hiệu \"dừng\" (giơ tay, im lặng) trước khi phát nhạc cụ. Nó giữ được giọng của bạn và cả buổi học."), prog=MUS)

A("G081", "memory-games-for-all", "Memory Activities for Learners with Disabilities", "Memory Games for Every Learner", "Trò chơi trí nhớ cho mọi học sinh",
  "vocab-grammar;listening-speaking", "beginner", "STEP 1–2", "Pre-A1–A1", "1-3;3-8", "15-20", "4-30", "table", "Remember me!", "I remember the cat! | And the ball!", "cat,ball,cup,hat",
  ("Real objects and picture cards; a tray and cloth; visual timers; simple choice boards.", "Đồ vật thật và thẻ tranh; khay và vải che; đồng hồ đếm giờ trực quan; bảng lựa chọn đơn giản."),
  ex(("B22", "Recall and name familiar words."), ("B11", "Listen and respond in a structured routine."), ("A12", "Take part with appropriate supports and choices.")),
  ("Memory games can be adapted for every learner, including those with learning differences. Clear routines, real objects and choice boards let all children succeed and build vocabulary.",
   "Trò chơi trí nhớ có thể điều chỉnh cho mọi học sinh, kể cả các em có khác biệt trong học tập. Nề nếp rõ ràng, đồ vật thật và bảng lựa chọn giúp mọi trẻ đều thành công và tăng vốn từ."),
  [("Routine", "Show the visual schedule and timer; name 3–4 objects.", "Nề nếp", "Cho xem lịch trực quan và đồng hồ; gọi tên 3–4 đồ vật."),
   ("Look and remember", "Children look at the tray for 20 seconds.", "Nhìn và nhớ", "Trẻ nhìn khay trong 20 giây."),
   ("What's missing?", "Cover, remove one object; children name or point to it.", "Cái gì biến mất?", "Che lại, lấy đi một vật; trẻ gọi tên hoặc chỉ vào thẻ tranh."),
   ("Choose and say", "Children choose a card from a choice board and name it.", "Chọn và nói", "Trẻ chọn thẻ trên bảng lựa chọn và gọi tên."),
   ("Celebrate", "Celebrate every answer: spoken, pointed or signed.", "Khen ngợi", "Khen mọi câu trả lời: nói, chỉ hay ra hiệu.")],
  (["We are learning to remember and name objects."], ["Chúng ta học cách ghi nhớ và gọi tên đồ vật."]),
  (["I can look and remember.", "I can show or say what is missing.", "I can choose and name a card."], ["Em có thể nhìn và ghi nhớ.", "Em có thể chỉ hoặc nói vật bị thiếu.", "Em có thể chọn và gọi tên một thẻ."]),
  ("fewer objects, more time, pointing accepted.", "ít đồ vật hơn, nhiều thời gian hơn, chấp nhận trả lời bằng cách chỉ."), ("more objects or remember two missing items.", "nhiều đồ vật hơn hoặc nhớ hai vật bị thiếu."),
  ("each child's preferred way to respond", "cách trả lời phù hợp với từng em"), ("Of learning: individual progress notes against each child's goals.", "Đánh giá kết quả học tập: ghi chú tiến bộ cá nhân theo mục tiêu của từng em."),
  (["Real objects and picture cards", "Tray and cloth", "Visual timer and choice board"], ["Đồ vật thật và thẻ tranh", "Khay và vải che", "Đồng hồ trực quan và bảng lựa chọn"]), INC,
  ("Use the same routine every lesson so children feel safe and know what comes next.", "Dùng cùng một nề nếp mỗi buổi để trẻ thấy an toàn và biết điều gì đến tiếp theo."),
  ("Link to GDPT 2018 inclusive-education guidance and early vocabulary units.", "Gắn với định hướng giáo dục hòa nhập và các Unit từ vựng đầu cấp GDPT 2018."),
  ("accepting pointing or gestures lets every child join in.", "chấp nhận trả lời bằng cách chỉ hoặc cử chỉ giúp mọi trẻ đều tham gia."),
  ("Talk to families and support staff about each child's strengths before the lesson. The best adaptation starts with what the child can already do.", "Trao đổi với phụ huynh và người hỗ trợ về điểm mạnh của từng em trước buổi học. Sự điều chỉnh tốt nhất bắt đầu từ những gì trẻ đã làm được."))

A("G082", "lucky-bottle-questions", "Lucky Bottle", "Lucky Bottle Questions", "Chai may mắn",
  "listening-speaking", "beginner;intermediate", "STEP 1–3", "A1–A2", "1-3;3-8;9-12", "15-20", "6-30", "floor", "Lucky bottle", "What's your favourite food? | My favourite food is phở!", "food,colour,animal,sport",
  ("A plastic bottle to spin; question cards by topic; a circle of chairs or floor space.", "Một chai nhựa để quay; thẻ câu hỏi theo chủ đề; vòng ghế hoặc khoảng sàn trống."),
  ex(("B13", "Ask and answer personal questions."), ("B15", "Use question forms correctly."), ("A11", "Listen and respond to classmates.")),
  ("Spinning a bottle adds suspense to simple questions. Everyone listens because they might be next, and answers are personal, so students learn about each other.",
   "Quay chai tạo sự hồi hộp cho những câu hỏi đơn giản. Ai cũng lắng nghe vì có thể đến lượt mình, và câu trả lời mang tính cá nhân nên học sinh hiểu thêm về nhau."),
  [("Make a circle", "Sit in a circle with the bottle in the middle.", "Ngồi vòng tròn", "Ngồi thành vòng tròn, chai ở giữa."),
   ("Model", "Spin; ask the person it points to: \"What's your favourite food?\"", "Làm mẫu", "Quay chai; hỏi người được chỉ: \"What's your favourite food?\""),
   ("Spin and ask", "The spinner picks a card and asks; the chosen student answers.", "Quay và hỏi", "Người quay rút thẻ và hỏi; bạn được chọn trả lời."),
   ("Follow up", "The class asks one follow-up question.", "Hỏi thêm", "Cả lớp hỏi thêm một câu."),
   ("Lucky facts", "Each student shares one fact they learned about a classmate.", "Điều thú vị", "Mỗi em kể một điều mới biết về một bạn.")],
  (["We are learning to ask and answer personal questions."], ["Chúng ta học cách hỏi và trả lời câu hỏi cá nhân."]),
  (["I can ask a question from the card.", "I can answer in a full sentence.", "I can remember a friend's answer."], ["Em có thể hỏi câu trên thẻ.", "Em có thể trả lời bằng câu đầy đủ.", "Em có thể nhớ câu trả lời của bạn."]),
  ("answer frames on the back of each card.", "khung trả lời ở mặt sau mỗi thẻ."), ("create their own questions and use follow-up \"why\".", "tự đặt câu hỏi và hỏi thêm \"why\"."),
  ("question forms and full answers", "câu hỏi và câu trả lời đầy đủ"), ("Of learning: each student reports one classmate fact in a sentence.", "Đánh giá kết quả học tập: mỗi em kể một điều về bạn bằng một câu."),
  (["Plastic bottle", "Question cards"], ["Chai nhựa", "Thẻ câu hỏi"]), SPK,
  ("Several small circles (one per group of 8) instead of one big circle.", "Nhiều vòng nhỏ (mỗi nhóm 8 em) thay vì một vòng lớn."),
  ("Link to GDPT 2018 Grades 3–9: personal information and preferences.", "Gắn với GDPT 2018 lớp 3–9: thông tin cá nhân và sở thích."),
  ("small spinning circles let many students speak at the same time.", "nhiều vòng quay nhỏ giúp nhiều em nói cùng lúc."),
  ("Add a \"pass\" card each student can use once. Knowing they can pass makes shy students more willing to play.", "Thêm một thẻ \"bỏ lượt\" mỗi em dùng được một lần. Biết mình có thể bỏ lượt khiến học sinh nhút nhát sẵn lòng chơi hơn."))

A("G083", "ant-grasshopper-puppets", "Storytelling with Puppets – The Ant and the Grasshopper", "The Ant and the Grasshopper", "Kiến và châu chấu",
  "listening-speaking;reading", "beginner;intermediate", "STEP 1–3", "A1–A2", "1-3;3-8", "35-45", "8-45", "board", "Ant & Grasshopper", "I'm working hard for winter. | I'm singing and playing!", "ant,grasshopper,summer,winter",
  ("The Aesop fable (public domain) in simple English; ant and grasshopper puppets; a story map.", "Truyện ngụ ngôn Aesop (miễn phí bản quyền) bằng tiếng Anh đơn giản; rối kiến và châu chấu; sơ đồ câu chuyện."),
  ex(("C26", "Retell the main events and the moral."), ("B13", "Perform dialogue in role."), ("C25", "Connect the story to their own life.")),
  ("A familiar fable with a clear moral is easy to follow and retell. Puppets make the dialogue lively, and discussing the moral brings in real opinions.",
   "Truyện ngụ ngôn quen thuộc với bài học rõ ràng dễ theo dõi và kể lại. Rối làm lời thoại sinh động, còn bàn về bài học mang lại ý kiến thật của học sinh."),
  [("Predict", "Show the two puppets; ask: \"Who works hard? Who plays?\"", "Dự đoán", "Cho xem hai con rối; hỏi: \"Who works hard? Who plays?\""),
   ("Tell the story", "Tell the fable with puppets; pause to ask questions.", "Kể chuyện", "Kể truyện bằng rối; dừng lại để đặt câu hỏi."),
   ("Story map", "Groups complete a story map: summer, winter, problem, ending.", "Sơ đồ câu chuyện", "Các nhóm hoàn thành sơ đồ: mùa hè, mùa đông, vấn đề, kết thúc."),
   ("Puppet retell", "Pairs retell with puppets.", "Kể lại bằng rối", "Từng cặp kể lại bằng rối."),
   ("The moral", "Discuss: \"What can we learn?\" Students share an opinion.", "Bài học", "Thảo luận: \"What can we learn?\" Học sinh nêu ý kiến.")],
  (["We are learning to retell a story.", "We are learning to talk about a story's message."], ["Chúng ta học cách kể lại câu chuyện.", "Chúng ta học cách nói về thông điệp của câu chuyện."]),
  (["I can retell the story in order.", "I can say my character's lines.", "I can say what the story teaches."], ["Em có thể kể lại câu chuyện theo thứ tự.", "Em có thể nói lời thoại của nhân vật.", "Em có thể nói câu chuyện dạy điều gì."]),
  ("picture story map and one line each.", "sơ đồ bằng tranh và mỗi em một câu thoại."), ("change the ending and explain the new moral.", "đổi kết thúc và giải thích bài học mới."),
  ("retelling sequence", "trình tự kể lại"), ("Of learning: puppet retell with a story-map check.", "Đánh giá kết quả học tập: kể lại bằng rối có đối chiếu sơ đồ câu chuyện."),
  (["Fable text", "Puppets", "Story maps"], ["Bài truyện ngụ ngôn", "Rối", "Sơ đồ câu chuyện"]), SPK,
  ("Desk pairs retell to each other; two pairs perform for the class.", "Từng cặp bàn kể cho nhau; hai cặp diễn trước lớp."),
  ("Link to GDPT 2018 Grades 4–7: stories and moral lessons.", "Gắn với GDPT 2018 lớp 4–7: truyện kể và bài học đạo đức."),
  ("Vietnamese students know similar fables, so they can compare and explain.", "học sinh Việt Nam biết các truyện ngụ ngôn tương tự nên có thể so sánh và giải thích."),
  ("Ask: \"Was the ant kind?\" There is no single right answer, and students who usually stay quiet often have strong opinions.", "Hỏi: \"Kiến có tốt bụng không?\" Không có đáp án duy nhất, và những em thường im lặng lại hay có ý kiến rất rõ ràng."))

A("G084", "prediction-game", "Prediction Game", "What Happens Next?", "Điều gì xảy ra tiếp theo?",
  "reading;listening-speaking", "beginner;intermediate", "STEP 2–3", "A1–A2", "3-8", "20-25", "8-45", "board", "Predict!", "I think the boy will fall. | I think he'll catch it!", "think,will,maybe,because",
  ("A short picture story or video cut into parts; prediction cards (\"I think… because…\").", "Truyện tranh hoặc video ngắn chia thành nhiều phần; thẻ dự đoán (\"I think… because…\")."),
  ex(("C23", "Make and confirm predictions while reading."), ("B15", "Use will and \"I think… because…\"."), ("B13", "Justify a prediction to the class.")),
  ("Stopping a story at an exciting moment makes everyone want to guess. Predicting with reasons is a key reading strategy and real speaking practice.",
   "Dừng câu chuyện ở khoảnh khắc hấp dẫn khiến ai cũng muốn đoán. Dự đoán kèm lý do là chiến lược đọc quan trọng và là luyện nói thật."),
  [("Look at part 1", "Show the first picture; describe it together.", "Xem phần 1", "Cho xem tranh đầu tiên; cùng mô tả."),
   ("Predict", "Students write \"I think… because…\" on a card.", "Dự đoán", "Học sinh viết \"I think… because…\" lên thẻ."),
   ("Reveal", "Show the next part; who was right?", "Mở ra", "Cho xem phần tiếp theo; ai đoán đúng?"),
   ("Predict again", "Repeat for 3–4 parts, giving reasons each time.", "Dự đoán tiếp", "Lặp lại 3–4 phần, mỗi lần nêu lý do."),
   ("Best ending", "Groups invent their own ending and vote.", "Kết thúc hay nhất", "Các nhóm sáng tác kết thúc riêng và bình chọn.")],
  (["We are learning to predict while reading.", "We are learning to give reasons."], ["Chúng ta học cách dự đoán khi đọc.", "Chúng ta học cách nêu lý do."]),
  (["I can predict with \"I think… will…\".", "I can give a reason with because.", "I can check my prediction."], ["Em có thể dự đoán với \"I think… will…\".", "Em có thể nêu lý do với because.", "Em có thể kiểm tra dự đoán của mình."]),
  ("choose from two prediction pictures.", "chọn giữa hai tranh dự đoán."), ("write an alternative ending with dialogue.", "viết kết thúc khác có lời thoại."),
  ("reasons given for predictions", "các lý do học sinh đưa ra"), ("Of learning: prediction cards with reasons.", "Đánh giá kết quả học tập: thẻ dự đoán có lý do."),
  (["Picture story or video parts", "Prediction cards"], ["Truyện tranh hoặc các đoạn video", "Thẻ dự đoán"]), SPK,
  ("Use the textbook reading: cover the end and predict before reading.", "Dùng bài đọc trong sách: che phần cuối và dự đoán trước khi đọc."),
  ("Link to GDPT 2018 pre-reading tasks in every unit.", "Gắn với các hoạt động trước khi đọc trong mọi Unit GDPT 2018."),
  ("covering the end of a textbook text makes any reading lesson exciting.", "che phần cuối bài đọc trong sách giúp mọi tiết đọc hấp dẫn hơn."),
  ("Reward the best reason, not the right guess. Students learn that thinking matters more than being lucky.", "Hãy khen lý do hay nhất, không phải dự đoán đúng. Học sinh hiểu rằng suy luận quan trọng hơn may mắn."))

A("G085", "ten-flashcard-games", "Teaching with Flashcards", "Ten Flashcard Games", "Mười trò chơi với thẻ từ",
  "vocab-grammar;listening-speaking", "beginner", "STEP 1–2", "Pre-A1–A1", "1-3;3-8", "15-20", "8-45", "board", "Flashcard games", "Slow reveal… a cat! | Jump on 'dog'!", "cat,dog,sun,cup",
  ("One set of picture flashcards for the unit.", "Một bộ thẻ tranh của Unit."),
  ex(("B22", "Learn and recall unit vocabulary."), ("B11", "Respond quickly to words heard."), ("A12", "Take part in fast whole-class games.")),
  ("One set of flashcards can power many different games: slow reveal, flash, what's missing, jump on it, whisper. Changing the game keeps repetition fresh, which is how vocabulary sticks.",
   "Một bộ thẻ có thể dùng cho rất nhiều trò: hé dần, chớp thẻ, cái gì biến mất, nhảy lên thẻ, thì thầm. Thay đổi trò chơi giúp sự lặp lại luôn mới mẻ, và đó là cách từ vựng được ghi nhớ."),
  [("Slow reveal", "Pull a card slowly out of an envelope; students guess.", "Hé dần", "Rút thẻ từ từ ra khỏi phong bì; học sinh đoán."),
   ("Flash", "Flash cards quickly; students shout the word.", "Chớp thẻ", "Chớp thẻ thật nhanh; học sinh hô to từ."),
   ("What's missing?", "Stick cards on the board, remove one; students name it.", "Cái gì biến mất?", "Dán thẻ lên bảng, lấy đi một thẻ; học sinh nói tên."),
   ("Jump on it", "Cards on the floor; call a word; a student jumps on it.", "Nhảy lên thẻ", "Đặt thẻ dưới sàn; đọc một từ; một em nhảy lên thẻ đó."),
   ("Whisper chain", "Whisper a word down a row; the last student points to the card.", "Chuỗi thì thầm", "Thì thầm một từ dọc dãy; em cuối chỉ vào thẻ.")],
  (["We are learning unit vocabulary through games."], ["Chúng ta học từ vựng của Unit qua trò chơi."]),
  (["I can name the cards quickly.", "I can find the card I hear.", "I can say which card is missing."], ["Em có thể gọi tên thẻ nhanh.", "Em có thể tìm thẻ em nghe.", "Em có thể nói thẻ nào bị thiếu."]),
  ("point instead of saying; fewer cards.", "chỉ thay vì nói; ít thẻ hơn."), ("say a sentence with each word.", "đặt câu với mỗi từ."),
  ("words recognized quickly", "những từ được nhận ra nhanh"), ("Of learning: each child names 6 cards.", "Đánh giá kết quả học tập: mỗi em gọi tên 6 thẻ."),
  (["Picture flashcards", "Envelope"], ["Thẻ tranh", "Phong bì"]), (["Teacher training", "Flashcard games are standard in primary ESL", "Flashcards are widely used; variety keeps them fresh"], ["Bồi dưỡng giáo viên", "Trò chơi thẻ là chuẩn mực ở lớp ESL tiểu học", "Thẻ từ được dùng rộng rãi; đa dạng hóa giúp luôn mới"]),
  ("Whisper chains and what's missing work with 45 students with no movement.", "Chuỗi thì thầm và cái gì biến mất chơi được với 45 em mà không cần di chuyển."),
  ("Link to GDPT 2018 vocabulary at the start of every unit (Grades 3–5).", "Gắn với phần từ vựng đầu mỗi Unit GDPT 2018 (lớp 3–5)."),
  ("rotating 2–3 flashcard games per lesson keeps 35-minute lessons lively.", "xoay vòng 2–3 trò chơi thẻ mỗi tiết giúp tiết 35 phút sôi nổi."),
  ("Keep cards in a box with a different game written on each day of the week. Teachers never run out of ideas, and students look forward to \"Friday's game\".", "Cất thẻ trong hộp, ghi mỗi ngày trong tuần một trò khác. Giáo viên không bao giờ cạn ý tưởng, học sinh háo hức chờ \"trò chơi thứ Sáu\"."))

A("G086", "party-planning", "Teenagers – Night Party", "Plan a Class Party", "Lên kế hoạch tiệc lớp",
  "listening-speaking;writing", "intermediate;advanced", "STEP 3–5", "A2–B1", "9-12", "35-45", "8-45", "table", "Party planning", "Why don't we have pizza? | That's a great idea!", "Let's,why not,budget,date",
  ("Planning sheet (date, food, music, games, budget); suggestion and agreement phrase cards.", "Phiếu kế hoạch (ngày, đồ ăn, âm nhạc, trò chơi, ngân sách); thẻ câu gợi ý và đồng ý."),
  ex(("B13", "Make suggestions and negotiate in a group."), ("B15", "Use suggestion forms (Let's…, Why don't we…, How about…)."), ("D14", "Write a clear event plan and invitation.")),
  ("Planning a real or imagined party gives teenagers something they care about to negotiate. Making suggestions, agreeing and disagreeing politely are key skills for group work.",
   "Lên kế hoạch cho một bữa tiệc thật hay tưởng tượng cho học sinh tuổi teen điều các em quan tâm để thương lượng. Đưa gợi ý, đồng ý và phản đối lịch sự là kỹ năng then chốt khi làm việc nhóm."),
  [("Suggestion phrases", "Teach Let's…, Why don't we…, How about…, I'm not sure about…", "Câu gợi ý", "Dạy Let's…, Why don't we…, How about…, I'm not sure about…"),
   ("Brainstorm", "Groups list ideas for food, music and games.", "Động não", "Các nhóm liệt kê ý tưởng về đồ ăn, nhạc và trò chơi."),
   ("Negotiate", "Groups agree within a budget using the phrases.", "Thương lượng", "Các nhóm thống nhất trong ngân sách bằng các mẫu câu."),
   ("Write the plan", "Groups complete the plan and write an invitation.", "Viết kế hoạch", "Các nhóm hoàn thành kế hoạch và viết thư mời."),
   ("Pitch", "Groups pitch their party; the class votes.", "Thuyết trình", "Các nhóm giới thiệu bữa tiệc; cả lớp bình chọn.")],
  (["We are learning to make suggestions and negotiate.", "We are learning to write an event plan."], ["Chúng ta học cách đưa gợi ý và thương lượng.", "Chúng ta học cách viết kế hoạch sự kiện."]),
  (["I can make suggestions in three ways.", "I can agree and disagree politely.", "I can write a clear invitation."], ["Em có thể đưa gợi ý theo ba cách.", "Em có thể đồng ý và phản đối lịch sự.", "Em có thể viết thư mời rõ ràng."]),
  ("phrase cards on the desk.", "thẻ mẫu câu trên bàn."), ("add a budget table and justify spending.", "thêm bảng ngân sách và giải thích các khoản chi."),
  ("suggestion and agreement language", "ngôn ngữ gợi ý và đồng ý"), ("Of learning: group plan and invitation.", "Đánh giá kết quả học tập: kế hoạch và thư mời của nhóm."),
  (["Planning sheets", "Phrase cards"], ["Phiếu kế hoạch", "Thẻ mẫu câu"]), SPK,
  ("Plan the real end-of-term class party in English.", "Lên kế hoạch thật cho buổi liên hoan cuối kỳ của lớp bằng tiếng Anh."),
  ("Link to GDPT 2018 Grades 9–11: making suggestions and invitations.", "Gắn với GDPT 2018 lớp 9–11: đưa gợi ý và lời mời."),
  ("planning a real class event makes the English matter.", "lên kế hoạch cho sự kiện thật của lớp khiến tiếng Anh có ý nghĩa."),
  ("Give each group a secret role card (\"You want a quiet party\"). Built-in disagreement produces much richer negotiation.", "Phát cho mỗi nhóm thẻ vai bí mật (\"You want a quiet party\"). Sự bất đồng được cài sẵn tạo ra cuộc thương lượng phong phú hơn nhiều."))

A("G087", "simon-says", "", "Simon Says", "Simon bảo",
  "listening-speaking", "beginner", "STEP 1", "Pre-A1–A1", "1-3", "5-10", "8-45", "floor", "Simon says…", "Simon says touch your nose! | Jump! (No Simon!)", "touch,nose,jump,clap",
  ("No materials needed.", "Không cần đồ dùng."),
  ex(("B11", "Listen carefully and follow instructions."), ("B22", "Recognize body parts and action verbs."), ("A12", "Follow game rules and self-check.")),
  ("Simon Says trains careful listening: students must notice whether \"Simon says\" is there. It is a classic total-physical-response game for body parts and actions.",
   "Simon bảo rèn kỹ năng nghe cẩn thận: học sinh phải để ý có câu \"Simon says\" hay không. Đây là trò chơi kinh điển phản hồi bằng vận động toàn thân cho bộ phận cơ thể và hành động."),
  [("Warm up", "Review body parts by touching and naming.", "Khởi động", "Ôn bộ phận cơ thể bằng cách chạm và gọi tên."),
   ("Explain", "Only move when you hear \"Simon says\".", "Giải thích", "Chỉ làm khi nghe \"Simon says\"."),
   ("Play", "Give quick commands; students who move without \"Simon says\" sit down.", "Chơi", "Đưa lệnh nhanh; em nào làm khi không có \"Simon says\" thì ngồi xuống."),
   ("Student Simon", "A student becomes Simon.", "Học sinh làm Simon", "Một học sinh làm Simon."),
   ("Cool down", "Slow commands: \"Simon says sit down quietly.\"", "Thả lỏng", "Lệnh chậm: \"Simon says sit down quietly.\"")],
  (["We are learning to listen carefully.", "We are learning body parts and actions."], ["Chúng ta học cách nghe cẩn thận.", "Chúng ta học bộ phận cơ thể và hành động."]),
  (["I can follow \"Simon says\" commands.", "I can stop when Simon doesn't say.", "I can give a command as Simon."], ["Em có thể làm theo lệnh \"Simon says\".", "Em có thể dừng khi Simon không nói.", "Em có thể ra lệnh khi làm Simon."]),
  ("model each action with the teacher.", "làm theo động tác mẫu của giáo viên."), ("give commands with two actions.", "ra lệnh với hai hành động."),
  ("listening accuracy", "độ chính xác khi nghe"), ("Of learning: giving three correct commands as Simon.", "Đánh giá kết quả học tập: ra ba lệnh đúng khi làm Simon."),
  (["None"], ["Không cần"]), SPK,
  ("Play standing at desks; \"out\" students become judges instead of sitting.", "Chơi đứng tại chỗ; em bị loại làm giám khảo thay vì ngồi xuống."),
  ("Link to GDPT 2018 Grade 3: body parts and classroom instructions.", "Gắn với GDPT 2018 lớp 3: bộ phận cơ thể và mệnh lệnh lớp học."),
  ("a 3-minute Simon Says wakes up any class with no preparation.", "Simon bảo 3 phút đánh thức bất kỳ lớp nào mà không cần chuẩn bị."),
  ("Don't make students sit out for long. Let them rejoin after one round so the weakest listeners keep practising.", "Đừng để học sinh bị loại ngồi ngoài quá lâu. Cho các em vào lại sau một vòng để những em nghe yếu được tiếp tục luyện."), prog=PE)

A("G088", "two-truths-one-lie", "", "Two Truths and a Lie", "Hai thật một giả",
  "listening-speaking;vocab-grammar", "intermediate;advanced", "STEP 3–5", "A2–B1", "3-8;9-12;adult", "15-20", "8-45", "pairs", "Two truths, one lie", "I have been to Canada. | Hmm… that's the lie!", "true,lie,I have,I can",
  ("Small cards or notebooks to write three sentences.", "Thẻ nhỏ hoặc vở để viết ba câu."),
  ex(("B13", "Share personal information and ask probing questions."), ("B15", "Use present perfect, can and past tense accurately."), ("B12", "Listen critically and ask for details.")),
  ("Students write three statements about themselves, one false. Classmates must question and listen closely to find the lie, which makes grammar practice personal and fun.",
   "Học sinh viết ba câu về bản thân, một câu sai. Các bạn phải đặt câu hỏi và lắng nghe kỹ để tìm câu sai, khiến việc luyện ngữ pháp trở nên cá nhân và thú vị."),
  [("Model", "Write three sentences about yourself; students guess the lie.", "Làm mẫu", "Viết ba câu về bản thân; học sinh đoán câu sai."),
   ("Write", "Students write two truths and one lie.", "Viết", "Học sinh viết hai câu thật và một câu giả."),
   ("Question", "In pairs or groups, partners ask questions to find the lie.", "Đặt câu hỏi", "Theo cặp hoặc nhóm, các bạn đặt câu hỏi để tìm câu giả."),
   ("Guess and reveal", "Partners guess; the writer reveals the lie.", "Đoán và tiết lộ", "Các bạn đoán; người viết tiết lộ câu giả."),
   ("Surprising facts", "The class shares the most surprising true facts.", "Điều bất ngờ", "Cả lớp chia sẻ những điều thật bất ngờ nhất.")],
  (["We are learning to share personal facts accurately.", "We are learning to ask questions to check information."], ["Chúng ta học cách chia sẻ thông tin cá nhân chính xác.", "Chúng ta học cách đặt câu hỏi để kiểm tra thông tin."]),
  (["I can write three correct sentences about myself.", "I can ask follow-up questions.", "I can explain my guess."], ["Em có thể viết ba câu đúng về bản thân.", "Em có thể hỏi thêm.", "Em có thể giải thích dự đoán của mình."]),
  ("sentence frames (I can…, I have…, I like…).", "khung câu (I can…, I have…, I like…)."), ("use a target tense for all three sentences.", "dùng một thì cụ thể cho cả ba câu."),
  ("accuracy of target forms", "độ chính xác của cấu trúc cần luyện"), ("Of learning: three accurate written sentences.", "Đánh giá kết quả học tập: ba câu viết chính xác."),
  (["Cards or notebooks"], ["Thẻ hoặc vở"]), SPK,
  ("Desk partners play, then swap with the pair behind.", "Bạn cùng bàn chơi trước, sau đó đổi với cặp bàn sau."),
  ("Link to GDPT 2018 Grades 6–10: present perfect and personal experiences.", "Gắn với GDPT 2018 lớp 6–10: thì hiện tại hoàn thành và trải nghiệm cá nhân."),
  ("a target tense turns this classic game into grammar practice.", "một thì cụ thể biến trò chơi kinh điển này thành luyện ngữ pháp."),
  ("Allow only yes/no questions. Students must think harder about how to ask, which is the real language workout.", "Chỉ cho phép câu hỏi yes/no. Học sinh phải nghĩ kỹ cách hỏi, đó mới là phần luyện ngôn ngữ thật."))

A("G089", "story-chain", "", "Story Chain", "Chuỗi câu chuyện",
  "listening-speaking;writing", "intermediate", "STEP 2–4", "A2–B1", "3-8;9-12", "15-20", "8-45", "table", "Story chain", "One day, a dragon… | …lost its shoes!", "One day,Then,Suddenly,Finally",
  ("A story-starter sentence; connector cards (then, suddenly, but, finally); a sheet to write the story.", "Một câu mở đầu câu chuyện; thẻ từ nối (then, suddenly, but, finally); tờ giấy để viết câu chuyện."),
  ex(("D12", "Generate ideas to continue a story."), ("B12", "Listen to previous sentences to stay consistent."), ("B31", "Use connectors to link sentences.")),
  ("Each student adds one sentence, so everyone must listen to keep the story going. Connectors become tools for building a logical, often hilarious, story.",
   "Mỗi em thêm một câu, nên ai cũng phải lắng nghe để câu chuyện tiếp diễn. Từ nối trở thành công cụ xây dựng câu chuyện hợp lý và thường rất buồn cười."),
  [("Starter", "Read a starter: \"One day, a dragon woke up in our classroom.\"", "Câu mở đầu", "Đọc câu mở đầu: \"One day, a dragon woke up in our classroom.\""),
   ("Connectors", "Show connector cards; model one sentence with \"Suddenly…\".", "Từ nối", "Giới thiệu thẻ từ nối; làm mẫu một câu với \"Suddenly…\"."),
   ("Chain", "Groups add one sentence each, using a connector card.", "Nối chuỗi", "Các nhóm lần lượt thêm một câu, dùng thẻ từ nối."),
   ("Write it down", "Groups write the full story.", "Viết lại", "Các nhóm viết lại cả câu chuyện."),
   ("Read aloud", "Groups read their story; the class picks the funniest.", "Đọc to", "Các nhóm đọc câu chuyện; cả lớp chọn chuyện vui nhất.")],
  (["We are learning to build a story together.", "We are learning to use connectors."], ["Chúng ta học cách cùng xây dựng câu chuyện.", "Chúng ta học cách dùng từ nối."]),
  (["I can add a sentence that fits.", "I can use a connector.", "I can help write the group story."], ["Em có thể thêm câu phù hợp.", "Em có thể dùng từ nối.", "Em có thể cùng nhóm viết câu chuyện."]),
  ("a picture prompt and sentence starter for their turn.", "tranh gợi ý và câu mở đầu cho lượt của mình."), ("add dialogue and a twist ending.", "thêm lời thoại và kết thúc bất ngờ."),
  ("connectors and story logic", "từ nối và tính logic của câu chuyện"), ("Of learning: the written group story.", "Đánh giá kết quả học tập: câu chuyện nhóm đã viết."),
  (["Story starters", "Connector cards", "Writing sheets"], ["Câu mở đầu", "Thẻ từ nối", "Giấy viết"]), SPK,
  ("Pass a paper along each row; each student writes one sentence.", "Chuyền một tờ giấy dọc mỗi dãy; mỗi em viết một câu."),
  ("Link to GDPT 2018 Grades 6–9: narrative writing and connectors.", "Gắn với GDPT 2018 lớp 6–9: viết tự sự và từ nối."),
  ("a written chain along each row involves all 45 students at once.", "chuỗi viết dọc mỗi dãy giúp cả 45 em cùng tham gia."),
  ("Fold the paper so each writer sees only the previous sentence. The surprises when the story is unfolded are unforgettable.", "Gấp giấy để mỗi người chỉ thấy câu ngay trước. Những bất ngờ khi mở tờ giấy ra thật khó quên."))

A("G090", "draw-and-guess", "", "Draw and Guess", "Vẽ và đoán",
  "vocab-grammar;listening-speaking", "beginner;intermediate", "STEP 1–3", "A1–A2", "1-3;3-8", "15-20", "8-45", "board", "Draw and guess", "Is it a house? | Yes! It's a house!", "house,tree,car,cake",
  ("Word cards from the unit; board or mini whiteboards; a timer.", "Thẻ từ của Unit; bảng lớn hoặc bảng con; đồng hồ bấm giờ."),
  ex(("B22", "Recall and name unit vocabulary."), ("B15", "Ask yes/no questions (Is it a…?)."), ("A12", "Cooperate in a team game.")),
  ("Drawing a word without speaking makes the team guess in English. Quick, visual and full of laughter, it is a reliable way to review a unit's vocabulary.",
   "Vẽ một từ mà không được nói buộc cả đội phải đoán bằng tiếng Anh. Nhanh, trực quan và đầy tiếng cười, đây là cách ôn từ vựng của Unit rất hiệu quả."),
  [("Review words", "Show the word cards and say them together.", "Ôn từ", "Cho xem thẻ từ và cùng đọc."),
   ("Model", "Draw a word; students guess: \"Is it a…?\"", "Làm mẫu", "Vẽ một từ; học sinh đoán: \"Is it a…?\""),
   ("Team rounds", "One drawer per team; 60 seconds; the team guesses in full questions.", "Các lượt theo đội", "Mỗi đội một người vẽ; 60 giây; cả đội đoán bằng câu hỏi đầy đủ."),
   ("Steal", "If time runs out, another team can steal with one guess.", "Giành điểm", "Hết giờ thì đội khác được giành điểm với một lần đoán."),
   ("Write", "Students write five words from the game with a quick sketch.", "Viết", "Học sinh viết năm từ trong trò chơi kèm hình vẽ nhanh.")],
  (["We are learning to review unit words.", "We are learning to ask \"Is it a…?\""], ["Chúng ta học cách ôn từ của Unit.", "Chúng ta học cách hỏi \"Is it a…?\""]),
  (["I can guess the word in a question.", "I can draw a clue without speaking.", "I can write the words."], ["Em có thể đoán từ bằng câu hỏi.", "Em có thể vẽ gợi ý mà không nói.", "Em có thể viết các từ."]),
  ("picture word list to choose from.", "danh sách từ có tranh để chọn."), ("draw phrases or sentences (\"a cat on a bike\").", "vẽ cụm từ hoặc câu (\"a cat on a bike\")."),
  ("question forms in guesses", "câu hỏi khi đoán"), ("Of learning: five words written correctly.", "Đánh giá kết quả học tập: viết đúng năm từ."),
  (["Word cards", "Board or mini whiteboards", "Timer"], ["Thẻ từ", "Bảng lớn hoặc bảng con", "Đồng hồ bấm giờ"]), SPK,
  ("Rows are teams; drawers come to the board in turn.", "Mỗi dãy một đội; người vẽ lần lượt lên bảng."),
  ("Link to GDPT 2018: vocabulary review in every unit.", "Gắn với GDPT 2018: ôn từ vựng trong mọi Unit."),
  ("a 10-minute draw-and-guess is a perfect end-of-unit review.", "vẽ và đoán 10 phút là hoạt động ôn cuối Unit lý tưởng."),
  ("Ban letters and numbers in the drawings. Students get creative, and the guessing team has to think about meaning, not spelling.", "Không cho viết chữ và số trong hình vẽ. Học sinh phải sáng tạo, và đội đoán phải nghĩ về nghĩa, không phải chính tả."))
